# Rock Paper Scissor Brains
class JyanKenPon:
	def __init__(self, pick1: str, pick2: str) -> None:
		self.result = {pick1:0, pick2:1}
	
	def check(self) -> int:
		"""
		Returns binary 0, 1 as for player 1 and player 2\n
		and -1 for a draw.\n\n

		Instead of multiple ifs expression (It's still multiple\n
		but lesser than before); Using the properties of a dict-\n
		ionary: duplications are not allowed making draws\n
		easier by only checking if the size of the dictionary is\n
		one; You could say "Why not a set? since it also doesn't\n
		allow duplicates", Well I need the key-value pair property\n
		of the dictionary to represent player one and two.\n
		"""

		if len(self.result) == 1:
			return -1
		if "rock" in self.result and "scissor" in self.result:
			return self.result["rock"]
		if "scissor" in self.result and "paper" in self.result:
			return self.result["scissor"]
		if "paper" in self.result and "rock" in self.result:
			return self.result["paper"]

class Config:
	@staticmethod
	def widgetTerminator(activeWidgets: list[tk.Widget] | tk.Widget) -> None:
	    if type(activeWidgets) == list:
	    	for obj in activeWidgets: 
	        	obj.destroy()
	    else:
	    	activeWidgets.destroy()

class HoverFrame(tk.Frame):
	frame_obj = [] # Contains only one object which is this Frame
	def __init__(self, text:str, widget_y: int, x_axis: int, y_axis: int, textSize: int | None = 15) -> None:
				# Offset the widget_y by 25 and continuosly offset the sum by the y axis-
				# inside the frame.
				# (140 + 25) + 2 		
		y_axis = (widget_y + 25 ) + y_axis
			
		# Checks if list already has an object
		if len(self.frame_obj) >= 1:
			# Updates the location of the object.
			# I'm doing this instead of destroying it-
			# everytime and updating frame by frame.
			# This removes frame stuttering.
			self.frame_obj[0].place(x=x_axis+30, y=y_axis)
			
		else:
			super().__init__()
			super().place(x=x_axis+30, y=y_axis)
			
			self.textlbl = tk.Label(self, 
				text=text, relief=tk.GROOVE, bd=2,
				font=("Comic Sans", textSize),
				bg="#FFFFFF")
			self.textlbl.grid(sticky="news")
			self.frame_obj.append(self)

	@classmethod
	def terminate(cls, root: tk.Tk) -> None:
		Config.widgetTerminator(cls.frame_obj)
		cls.frame_obj.clear()

class KeyBinds:
	def __init__(self, defaultRoot: tk.Tk, binds: dict[str, dict[tk.Widget, MethodType]] | dict[str, MethodType]) -> None:
	    """
	    To use a different frame/root, in binds you can add a dict,\n
	    and place the method like:\n
	                ...:{"root":..., "cmd":...}
	    """
	    self.active_binds = []
	    self.dRoot = defaultRoot
	    self.binds = binds

	def attach(self) -> None:
	    for _, binds in self.binds.items():
	        for key, obj in binds.items():
	            if not key[0] == "<" and not key[len(key)-1] == ">":
	                    key = f"<{key}>"

	            if type(obj) == MethodType:
	                ref = self.dRoot.bind(key, obj)
	                self.active_binds.append((self.dRoot, ref, key))

	            elif type(obj) == dict:
	                root = obj["root"]
	                cmd = obj["cmd"]

	                ref = root.bind(key, cmd)                  
	                self.active_binds.append((root, ref, key))

	def detach(self) -> None:
	    for root, funcid, key in self.active_binds:
	        root.unbind(key, funcid=funcid)

	    self.active_binds.clear()

class MatchesWindow(tk.Listbox):
	def __init__(self, results: dict) -> None:
		self.window = tk.Tk()
		self.window.resizable(False, False)
		self.window.title("Match Result/s")
		self.window.config(cursor="pencil")
		self.results = results	

		super().__init__(self.window, width=45, height=10, font=(20))
		super().pack(fill="both")

		section = 0
		for rnd, result in results.items():
			super().insert(section, f"Round: {rnd} {"[drew]" if result["result"] == -1 else ""}")
			super().insert(section+1, f"Azusa: {result["azusa"]} {"[won]" if result["result"] == 0 else ""}")
			super().insert(section+2, f"Ayane: {result["ayane"]} {"[won]" if result["result"] == 1 else ""}")
			super().insert(section+3, "================================")
			section+=4
		self.window.mainloop()

class BetGui(tk.Frame):
	def __init__(self, window: tk.Tk, rounds: int, chosen_bot: int) -> None:
		print(f"[{star_yellow}] Launched BetGui.")
		self.window = window
		self.window.geometry("600x350")
		self.window.config(cursor="watch", bg="#FFFFFF")
		self.azusa = tk.PhotoImage(data=azusa)
		self.shiawase_az = tk.PhotoImage(data=shiawase_az)
		self.ayane = tk.PhotoImage(data=ayane)
		self.shiawase_ay = tk.PhotoImage(data=shiawase_ay)

		self.rounds_label = tk.Label(self.window, font=("Arial", 20), bg="#FFFFFF")
		self.match_checker_btn = tk.Button(self.window, text="Check Match History", 
									 	  font=("Arial", 15), bg="#FFFFFF", state=tk.DISABLED, 
									 	  command=self.match_checking)
		self.azusa_score_label = tk.Label(self.window, font=("Arial", 20), bg="#FFFFFF")
		self.ayane_score_label = tk.Label(self.window, font=("Arial", 20), bg="#FFFFFF")

		self.icon1_frame = tk.Label(
									width=250, 
									height=250, 
									image=self.azusa,
									bg="#FFFFFF")
		self.icon1_label = tk.Label(text="Azusa", bg="#FFFFFF", font=("Arial", 15))
		self.icon2_frame = tk.Label(
									width=250, 
									height=250, 
									image=self.ayane,
									bg="#FFFFFF")
		self.icon2_label = tk.Label(text="Ayane", bg="#FFFFFF", font=("Arial", 15))

		self.rounds_label.place(x=25, y=300)
		self.match_checker_btn.place(x=200, y=300)
		self.match_checker_btn.tkraise()
		self.icon1_frame.place(x=25, y=25)
		self.icon2_frame.place(x=325, y=25)

		self.match_checker_btn.config()

		self.thread_stop = False
		self.rounds = rounds
		self.results = {}
		self.selected = chosen_bot

		self.bindings = {"window":{"Escape":self.keyboard_events}}
		self.load()

	def match_checking(self) -> None:
		MatchesWindow(self.results)

	def matches_start(self) -> None:
		print(f"[{star_green}] Match-Thread Started; Rounds: {self.rounds}")
		choices = ("rock", "paper", "scissor")
		azusa_score = 0
		ayane_score = 0
		true_finish = False
		finished_rounds = 0
		self.azusa_score_label.place(x=225, y=225)
		self.ayane_score_label.place(x=375, y=225)		
		try:
			while finished_rounds != self.rounds and not self.thread_stop and self.window.winfo_children():
				azusa = choice(choices)
				ayane = choice(choices)
				
				result = JyanKenPon(azusa, ayane).check()
				self.results[f"{finished_rounds+1}"] = {"azusa":azusa, "ayane":ayane, "result":result}

				if result == 0:
					azusa_score+=1
					self.azusa_score_label.config(text=azusa_score)
				elif result == 1:
					ayane_score+=1
					self.ayane_score_label.config(text=ayane_score)
				self.rounds_label.config(text=f"Round: {finished_rounds+1}")
				self.rounds_label.tkraise()
				self.azusa_score_label.tkraise()
				self.ayane_score_label.tkraise()
				finished_rounds+=1
				sleep(0.1)
		except RuntimeError:
			pass
		finally:
			true_finish = True if finished_rounds == self.rounds else False

		if true_finish:
			print(f"[{star_green}] Match-Thread Ended; Rounds: {finished_rounds}/{self.rounds}")
			if azusa_score > ayane_score:
				self.icon1_frame.config(bg="#c7fcae", image=self.shiawase_az)
				self.azusa_score_label.config(bg="#c7fcae")
			else:
				self.icon2_frame.config(bg="#c7fcae", image=self.shiawase_ay)
				self.ayane_score_label.config(bg="#c7fcae")
			self.thread_stop = True
			self.match_checker_btn.config(state=tk.ACTIVE, cursor="hand2")
			self.window.config(cursor="ul_angle", bg="#FFFFFF")
			self.window.title("じゃんけんぽん [Esc to return]")
		else:
			print(f"[{warning}] Match-Thread Ended Improperly; Rounds: {finished_rounds}/{self.rounds}")

	def load(self) -> None:
		game_thread = Thread(target=self.matches_start)
		game_thread.start()
		self.binds = KeyBinds(self.window, self.bindings)
		self.binds.attach()

	def keyboard_events(self, event) -> None:
		if event.keysym == "Escape" and self.thread_stop:
			self.binds.detach()
			Config.widgetTerminator(self.window.winfo_children())
			MainGui(self.window)
		elif not self.thread_stop:
			tk.messagebox.showerror(title="じゃんけんぽん",message="Matches still running..")

class MainGui(tk.Frame):
	def __init__(self, window: tk.Tk) -> None:
		print(f"[{star_yellow}] Launched MainGui.")
		self.window = window
		self.window.title("じゃんけんぽん")
		self.window.geometry("600x400")
		self.window.config(cursor="ul_angle", bg="#FFFFFF")
		self.azusa = tk.PhotoImage(data=azusa)
		self.shiawase_az = tk.PhotoImage(data=shiawase_az)
		self.ayane = tk.PhotoImage(data=ayane)
		self.shiawase_ay = tk.PhotoImage(data=shiawase_ay)
		
		# Variable Initialization
		self._ic1_selected = False
		self._ic2_selected = False
		self._selection_val = -1
		self.rounds = 0
		self.max_rounds = 1000

		# Widgets
		self.icon1_frame = tk.Label(
									width=250, 
									height=250, 
									image=self.azusa,
									bg="#FFFFFF")
		self.icon1_label = tk.Label(text="あずさ", bg="#FFFFFF", font=("Arial", 15))
		self.icon2_frame = tk.Label(
									width=250, 
									height=250, 
									image=self.ayane,
									bg="#FFFFFF")
		self.icon2_label = tk.Label(text="あやね", bg="#FFFFFF", font=("Arial", 15))

		
		self.rounds_frame = tk.Frame(self.window)
		self.start_btn = tk.Button(self.rounds_frame, text="Start Matches", font=("Arial", 15), 
								   command=self.rounds_start, cursor="iron_cross", state=tk.DISABLED)
		self.min_max_label = tk.Label(self.rounds_frame, text="Rounds", font=("Arial", 15),
									  bg="#FFFFFF")
		self.rounds_label = tk.Label(self.rounds_frame, text=f"Min: 5 Max: {self.max_rounds} ", 
									 font=("Arial", 15), bg="#FFFFFF")
		self.rounds_input = tk.Entry(self.rounds_frame, width=5, font=("Arial", 15))
		self.rounds_frame.rowconfigure(3, weight=1)
		self.min_max_label.grid(row=0, columnspan=2, sticky="news")
		self.rounds_label.grid(row=1, column=0, sticky="news")
		self.rounds_input.grid(row=1, column=1, sticky="news")
		self.start_btn.grid(row=2, columnspan=2, sticky="news")
		self.rounds_frame.place(x=175, y=305)


		self.icon1_label.place(x=25+100, y=280)
		self.icon2_label.place(x=25+405, y=280)
		self.icon1_frame.place(x=25, y=25)
		self.icon2_frame.place(x=325, y=25)

		self.bindings = {"window":{
								"Escape":self.keyboard_events},
						"ic1_evt_region":{
								"Enter": {"root":self.icon1_frame, "cmd":self.ic1_frames_events},
								"Motion": {"root":self.icon1_frame, "cmd":self.ic1_frames_events},
								"Leave": {"root":self.icon1_frame, "cmd":self.ic1_frames_events},
								"ButtonPress":{"root":self.icon1_frame, "cmd":self.ic1_frames_events}},
						"ic2_evt_region":{
								"Enter": {"root":self.icon2_frame, "cmd":self.ic2_frames_events},
								"Motion": {"root":self.icon2_frame, "cmd":self.ic2_frames_events},
								"Leave": {"root":self.icon2_frame, "cmd":self.ic2_frames_events},
								"ButtonPress":{"root":self.icon2_frame, "cmd":self.ic2_frames_events}},
						"rounds_region":{
								"Return":{"root":self.rounds_input, "cmd":self.keyboard_events}}
						}
		self.load()

	def rounds_start(self) -> None:
		if self.rounds != 0 and (self._ic1_selected or self._ic2_selected):
			confirm = tk.messagebox.askokcancel(title="じゃんけんぽん", message="Start Matches?")
			if confirm:
				self.binds.detach()
				Config.widgetTerminator(self.window.winfo_children())
				BetGui(self.window, self.rounds, self._selection_val)
		else:
			tk.messagebox.showerror(title="じゃんけんぽん", message="No Character has been selected.")

	def load(self) -> None:
		self.binds = KeyBinds(self.window, self.bindings)
		self.binds.attach()

	def ic1_frames_events(self, event: tk.Event) -> None:
		frame_rooty = self.icon1_frame.winfo_y()
		
		if (event.y <= 240 and event.y >= 20) and (event.x <= 196 and event.x >= 53):
			self.icon1_frame.config(cursor="heart")

			if self._ic1_selected:
				text = "Right click to undo selection"

				if event.num == 3:
					self.icon1_frame.config(bg="#FFFFFF")
					self.icon1_label.config(bg="#FFFFFF", fg="#000000")
					self._ic1_selected = False
					self._selection_val = -1
					HoverFrame.terminate(self.window)

				if event.type == '7': 
					HoverFrame(text, frame_rooty, event.x, event.y, 10)
				if event.type == '6':
					HoverFrame(text, frame_rooty, event.x-75, event.y, 10)

			else:
				text = "Left click to select" if not self._ic2_selected else "Left click to change"

				if event.num == 1:
					self.icon1_frame.config(bg="#bf5a82", image=self.azusa)
					#self.icon1_label.config(bg="#73ab5e", fg="#FFFFFF")
					if self._ic2_selected:
						self._ic2_selected = False
						self._ic1_selected = True
						self.icon2_frame.config(bg="#FFFFFF")
						#self.icon2_label.config(bg="#FFFFFF", fg="#000000")						
						self._selection_val = 0
					else:
						self._ic1_selected = True
						self._selection_val = 0	
					HoverFrame.terminate(self.window)
					
				if event.type == '7': 
					HoverFrame(text, frame_rooty, event.x, event.y, 10)
				if event.type == '6':
					HoverFrame(text, frame_rooty, event.x-50, event.y, 10)
					self.icon1_frame.config(bg="#f0c6f7", image=self.shiawase_az)
					#self.icon1_label.config(bg="#c7fcae", fg="#174d02")
					
		else:
			self.icon1_frame.config(cursor="ul_angle")
			HoverFrame.terminate(self.window)
			if not self._ic1_selected:
				self.icon1_frame.config(bg="#FFFFFF", image=self.azusa)
				#self.icon1_label.config(bg="#FFFFFF", fg="#000000")
				self.icon1_frame.place(x=25, y=25)

	def ic2_frames_events(self, event: tk.Event) -> None:
		frame_rooty = self.icon2_frame.winfo_y()

		if "Motion" not in self.bindings["window"]:
			self.bindings["window"]["Motion"] = self.keyboard_events
			self.binds.detach()
			self.binds.attach()
		try:
			if (event.y <= 246 and event.y >= 14) and (event.x <= 195 and event.x >= 55):
				self.icon2_frame.config(cursor="heart")

				if self._ic2_selected:
					text = "Right click to undo selection"

					if event.num == 3:
						self.icon2_frame.config(bg="#FFFFFF")
						#self.icon2_label.config(bg="#FFFFFF", fg="#000000")
						self._ic2_selected = False
						self._selection_val = -1
						HoverFrame.terminate(self.window)

					if event.type == '7':
						HoverFrame(text, frame_rooty, self.mirroring_x+225, event.y, 10)
					if event.type == '6':
						HoverFrame(text, frame_rooty, self.mirroring_x+225, event.y, 10)

				else:
					text = "Left click to select" if not self._ic1_selected else "Left click to change"

					if event.num == 1:
						self.icon2_frame.config(bg="#bf5a82", image=self.ayane)
						#self.icon2_label.config(bg="#73ab5e", fg="#FFFFFF")
						if self._ic1_selected:
							self._ic1_selected = False
							self._ic2_selected = True
							self.icon1_frame.config(bg="#FFFFFF")
							#self.icon1_label.config(bg="#FFFFFF", fg="#000000")
							self._selection_val = 1
						else:
							self._ic2_selected = True	
							self._selection_val = 1
						HoverFrame.terminate(self.window)
						
					if event.type == '7':
						HoverFrame(text, frame_rooty, self.mirroring_x+225, event.y, 10)
					if event.type == '6':
						HoverFrame(text, frame_rooty, self.mirroring_x+250, event.y, 10)
						self.icon2_frame.config(bg="#f0c6f7", image=self.shiawase_ay)
						#self.icon2_label.config(bg="#c7fcae", fg="#174d02")
						
			else:
				self.icon2_frame.config(cursor="ul_angle")
				HoverFrame.terminate(self.window)
				self.bindings["window"].pop("Motion")
				self.binds.detach()
				self.binds.attach()
				if not self._ic2_selected:
					self.icon2_frame.config(bg="#FFFFFF", image=self.ayane)
					self.icon2_label.config(bg="#FFFFFF", fg="#000000")
					self.icon2_frame.place(x=325, y=25)
		except AttributeError:
			pass

	def keyboard_events(self, event) -> None | int:
		self.mirroring_x = event.x

		if event.keysym == "Return":
			try:
				value = int(self.rounds_input.get())

				if value <= self.max_rounds and value >= 5:
					self.rounds = value
					self.start_btn.config(state=tk.ACTIVE, cursor="hand2")
				else:
					tk.messagebox.showerror(title="Max Round Reached", message=f"Max round: {self.max_rounds}\nMin round: 5")
					self.rounds = 0
					self.start_btn.config(state=tk.DISABLED, cursor="iron_cross")
			except ValueError:
				self.rounds = 0
				self.start_btn.config(state=tk.DISABLED, cursor="iron_cross")
		if event.keysym == "Escape":
			exit = tk.messagebox.askyesno(title="じゃんけんぽん", message="Exit this program?")
			if exit:
				print(f"[{star_yellow}] Exited The Program.")
				self.binds.detach()
				Config.widgetTerminator(self.window.winfo_children())
				self.window.destroy()

def imp_exit() -> None:
	print(f"[{warning}] Improperly Exited.")
	window.destroy()

